#!/usr/bin/env bash
# Fails when the repository has JavaScript files: the code is TypeScript (#219, CLAUDE.md).
# Looks at tracked and new files alike, so it also fails locally before the commit.
set -euo pipefail

# Generated by drizzle-kit and never edited by hand (07 §6).
ALLOWED='^drizzle/migrations\.js$'

found=$(git ls-files --cached --others --exclude-standard -- '*.js' '*.jsx' '*.mjs' '*.cjs' |
  grep -Ev "$ALLOWED" || true)

if [[ -n "$found" ]]; then
  echo "JavaScript files are not allowed: write them in TypeScript (CLAUDE.md)."
  echo "$found"
  exit 1
fi
